local RobloxCSharp = _G.RobloxCSharp or {}
-- Generated by CSharp.lua Compiler
local System = _G.System or require(game:GetService("ReplicatedStorage"):WaitForChild("CoreSystem"))
local Roblox
System.import(function (out)
  Roblox = out.Roblox
end)
System.namespace("RobloxCSharp.Entities", function (namespace)
  -- Класс Героя-Прыгуна: расширяет базового Героя и добавляет способность "Супер Прыжок Вверх"
  namespace.class("SuperJumperHero", function (namespace)
    local Initialize, SuperJump, UseAbility, CreateJumpAura, CreateJumpFlashEffect, UpdateOverheadText, __ctor__
    __ctor__ = function (this, player, character, humanoid)
      System.base(this).__ctor__(this, player, character, humanoid)
    end
    Initialize = function (this)
      System.base(this).Initialize(this)

      -- 1. Увеличиваем стандартную высоту прыжка персонажа
      if this.Humanoid ~= nil then
        this.Humanoid.UseJumpPower = true
        this.Humanoid.JumpPower = this.SuperJumpForce
      end

      -- 2. Добавляем золотистое свечение вокруг героя
      CreateJumpAura(this)

      -- 3. Обновляем надпись над головой
      UpdateOverheadText(this)

      System.Console.WriteLine("[Супер Прыгун] Герой " .. System.toString(this.Name) .. " готов к супер прыжкам!")

      -- 4. Сразу выполняем демонстрационный супер прыжок вверх при появлении
      SuperJump(this)
    end
    SuperJump = function (this)
      local rootPart = System.cast(Roblox.BasePart, this.Character:FindFirstChild("HumanoidRootPart", false))
      if rootPart == nil or this.Humanoid == nil then
        return
      end

      System.Console.WriteLine("🚀 [Способность] Герой " .. System.toString(this.Name) .. " выполняет СУПЕР ПРЫЖОК ВВЕРХ!")

      -- 1. Даем физический импульс вверх персонажу через скорость
      rootPart.AssemblyLinearVelocity = Vector3.new(0, this.SuperJumpForce, 0)

      -- 2. Активируем состояние прыжка у Humanoid
      this.Humanoid.Jump = true

      -- 3. Создаем яркую световую вспышку при прыжке
      CreateJumpFlashEffect(this, rootPart)
    end
    UseAbility = function (this)
      SuperJump(this)
    end
    CreateJumpAura = function (this)
      local oldHighlight = this.Character:FindFirstChild("JumpAura", false)
      if oldHighlight ~= nil then
        oldHighlight:Destroy()
      end

      local aura = Instance.new("Highlight")
      aura.Name = "JumpAura"
      aura.FillColor = Color3.fromRGB(255, 215, 0)
      -- Золотой цвет
      aura.OutlineColor = Color3.fromRGB(255, 255, 255)
      aura.FillTransparency = 0.5
      aura.OutlineTransparency = 0.1
      aura.Parent = this.Character
    end
    CreateJumpFlashEffect = function (this, rootPart)
      local light = Instance.new("PointLight")
      light.Name = "JumpFlash"
      light.Color = Color3.fromRGB(255, 230, 100)
      light.Brightness = 5
      light.Range = 20
      light.Parent = rootPart
    end
    UpdateOverheadText = function (this)
      local head = System.cast(Roblox.BasePart, this.Character:FindFirstChild("Head", false))
      if head == nil then
        return
      end

      local billboard = head:FindFirstChild("HeroOverhead", false)
      if billboard ~= nil then
        local label = System.cast(Roblox.TextLabel, billboard:FindFirstChild("TextLabel", false))
        if label ~= nil then
          label.Text = System.toString(this.Name) .. " [⚡ Супер Прыгун]"
          label.TextColor3 = Color3.fromRGB(255, 215, 0)
        end
      end
    end
    return {
      base = function (out)
        return {
          out.RobloxCSharp.Entities.Hero
        }
      end,
      SuperJumpForce = 120,
      Initialize = Initialize,
      SuperJump = SuperJump,
      UseAbility = UseAbility,
      __ctor__ = __ctor__
    }
  end)
end)

return true
